impl sts2_core::RelicTable for Relic {
    type Pool = RelicPool;
    type Rarity = RelicRarity;

    /// The pools that draft this relic.
    ///
    /// Never empty — unlike a monster's acts or an encounter's,
    /// every relic is in at least one pool — and three relics are in
    /// two.
    fn pools(self) -> &'static [RelicPool] {
        POOLS[self as usize]
    }

    /// Its rarity, which is also which screen offers it.
    fn rarity(self) -> RelicRarity {
        self.data().rarity
    }

    /// Whether taking it does something there and then.
    fn has_pickup_effect(self) -> bool {
        self.data().flags.get(RelicFlag::UponPickup) == Field::Constant(true)
    }

    /// What a merchant charges before the haggle.
    fn merchant_price(self) -> Option<u16> {
        match self.data().price {
            Price::Gold(gold) => Some(gold),
            Price::NotSold => None,
        }
    }

    /// Whether a merchant is allowed to stock it.
    fn allowed_in_shops(self) -> bool {
        self.data().flags.get(RelicFlag::AllowedInShops) == Field::Constant(true)
    }

    fn overrides(self) -> sts2_core::Overrides {
        OVERRIDES[self as usize]
    }
}

